## Steps

1. Copy the following script as `a.py` in the repository root.

```python
# a.py

"""
Automatically replace `%` formatting with f-string
"""
import ast
import sys
import re
import subprocess


def is_simple_expression(node: ast.AST) -> bool:
    """
    The following nodes are considered simple expressions:
    1. Name (e.g. a)
    2. Attribute consisting of only names (e.g. a.b.c)
    3. Call consisting of only names and without any any arguments (e.g. a.b.c())
    """
    if isinstance(node, ast.Name):
        return True
    elif isinstance(node, ast.Attribute):
        return is_simple_expression(node.value)
    elif isinstance(node, ast.Call):
        return (
            is_simple_expression(node.func)
            and len(node.keywords) == 0
            and all(is_simple_expression(arg) for arg in node.args)
        )
    elif isinstance(node, ast.Constant):
        return isinstance(node.value, (int, float))
    elif isinstance(node, ast.Tuple):
        return all(is_simple_expression(e) for e in node.elts)
    else:
        return False


PLACEHOLDER_PATTERN = re.compile(r"%[sd]")


class PercentFormatFinder(ast.NodeVisitor):
    def __init__(self):
        self.nodes = []

    def visit_BinOp(self, node: ast.BinOp):
        if (
            isinstance(node.op, ast.Mod)
            and isinstance(node.left, ast.Str)
            and is_simple_expression(node.right)
            and PLACEHOLDER_PATTERN.search(node.left.s)
            and node.lineno == node.end_lineno
        ):
            self.nodes.append(node)
        self.generic_visit(node)


def to_fstring(original: str, node: ast.BinOp) -> str:
    if isinstance(node.right, ast.Tuple):
        nodes = node.right.elts
    else:
        nodes = [node.right]
    left_orig = original[node.left.col_offset : node.left.end_col_offset]

    new = left_orig
    for n in nodes:
        right_orig = original[n.col_offset : n.end_col_offset]
        new = PLACEHOLDER_PATTERN.sub(f"{{{right_orig}}}", new, count=1)

    return original[: node.col_offset] + "f" + new + original[node.end_col_offset :]


def main():
    files = subprocess.check_output(["git", "ls-files", "**/*.py"]).decode().splitlines()
    counter = 0
    limit = 30

    for file in files:
        with open(file) as f:
            src = f.read()
            tree = ast.parse(src)
            visitor = PercentFormatFinder()
            visitor.visit(tree)

            if len(visitor.nodes) > 0:
                lines = src.split("\n")
                for node in visitor.nodes:
                    counter += 1
                    print(counter)
                    lines[node.lineno - 1] = to_fstring(lines[node.lineno - 1], node)

                    if counter == limit:
                        break

            else:
                continue

        with open(file, "w") as f:
            f.write("\n".join(lines))

        if counter == limit:
            break


if __name__ == "__main__":
    main()

```

2. Run `python a.py`
3. Verify the changes look correct.
4. File a PR. To make the PR reviewable, the script fixes up to 30 percent formattings.
5. Merge the PR and sync your local repo with upstream.
6. Repeat 2 ~ 5 until the script prints out nothing.
